mapper.select:
Select t1.* From (Select ct.TRANSACTION_ID, ct.TRANSACTION_NUM, ct.TRANSACTION_TYPE, cc.contract_name, cc.contract_number,
cc.manufacturer_id, (Select hm.bp_name From hls_bp_master hm Where hm.bp_id = cc.manufacturer_id) manufacturer_id_n, cc.bp_id_vender, (Select hm.bp_name From hls_bp_master hm Where hm.bp_id = cc.bp_id_vender) bp_id_vender_n, cc.factory_id, (Select hm.bp_name From hls_bp_master hm Where hm.bp_id = cc.factory_id) factory_id_n, ct.TRANSACTION_DATE, ct.TRANSACTION_AMOUNT,
nvl(ct.BLOCK_AMOUNT, 0) BLOCK_AMOUNT,
(nvl(ct.transaction_amount, 0) - (Select nvl(Sum(nvl(line.REFUND_AMOUNT, 0)), 0) From CSH_TRANSACTION_REFUND_LN line, CSH_TRANSACTION_REFUND r Where line.refund_id = r.refund_id And r.refund_status In ('NEW', 'REJECTED') And line.SOURCE_TRANSACTION_ID = ct.TRANSACTION_ID) - (Select nvl(Sum(cwo.csh_write_off_amount), 0) From csh_write_off cwo Where cwo.csh_transaction_id = ct.transaction_id And cwo.reversed_flag = 'N') - nvl(ct.BLOCK_AMOUNT, 0)) As can_return_amount,
(Select nvl(Sum(ll.REFUND_AMOUNT), 0) From CSH_TRANSACTION_REFUND_LN ll, CSH_TRANSACTION_REFUND r Where ll.refund_id = r.refund_id And r.refund_status = 'APPROVED' And ll.SOURCE_TRANSACTION_ID = ct.TRANSACTION_ID ) as return_write_off_amount, ( SELECT nvl(sum(ctr.REFUND_AMOUNT),0) FROM csh_transaction_refund ctr WHERE ctr.refund_status = 'APPROVING' AND ctr.TRANSACTION_ID = ct.TRANSACTION_ID ) refunding_amount,
ct.CURRENCY_CODE, ct.BANK_ACCOUNT_ID, ct.posted_flag, (Select cba.BANK_ACCOUNT_NUM From CSH_BANK_ACCOUNT cba Where cba.BANK_ACCOUNT_ID = ct.BANK_ACCOUNT_ID) As BANK_ACCOUNT_NUM, nvl(ct.WRITE_OFF_AMOUNT, 0) As WRITE_OFF_AMOUNT,
(Select m.BP_NAME From HLS_BP_MASTER m Where m.BP_ID = ct.BP_ID) As bp_name, (Select scvb.MEANING From SYS_CODE_B scb Left Join SYS_CODE_VALUE_B scvb On scb.CODE = 'CSH301_TRANSACTION_TYPE' And scb.CODE_ID = scvb.CODE_ID Where scvb.VALUE = ct.TRANSACTION_TYPE) As transaction_type_desc, (Select scvb.MEANING From SYS_CODE_B scb Left Join SYS_CODE_VALUE_B scvb On scb.CODE = 'CHS.CURRENCY_TYPE' And scb.CODE_ID = scvb.CODE_ID Where scvb.VALUE = ct.CURRENCY_CODE) As currency_code_desc,
decode((Select Count(1) From CON_CONTRACT_CASHFLOW ccc Where ccc.CONTRACT_ID = cc.CONTRACT_ID And ccc.CF_ITEM != 5 And ccc.CF_DIRECTION = 'INFLOW' And ccc.WRITE_OFF_FLAG != 'FULL'), 0, 'Y', 'N') is_terminate, (Select scvb.MEANING From SYS_CODE_B scb Left Join SYS_CODE_VALUE_B scvb On scb.CODE = 'SYS.YES_NO' And scb.CODE_ID = scvb.CODE_ID Where scvb.VALUE = decode((Select Count(1) From CON_CONTRACT_CASHFLOW ccc Where ccc.CONTRACT_ID = cc.CONTRACT_ID And ccc.CF_ITEM != 5 And ccc.CF_DIRECTION = 'INFLOW' And ccc.WRITE_OFF_FLAG != 'FULL'), 0, 'Y', 'N')) As is_terminate_n, ( select bm.bp_type from hls_bp_master bm where bm.bp_id=ct.bp_id )bp_type, (select hbt.description from hls_bp_master hbm left join hls_bp_type hbt on hbm.bp_type = hbt.bp_type where hbm.bp_id = ct.bp_id) as bp_name_category, ct.bp_id payment_bp_id, ct.bp_bank_name, ct.bp_bank_account_name, ct.bp_bank_account_num, ct.bank_slip_num From csh_transaction ct Left Join con_contract cc On ct.CONTRACT_ID = cc.contract_id Where ct.TRANSACTION_TYPE In ('ADVANCE_RECEIPT', 'DEPOSIT', 'MANAGEMENT_FEE', 'PERFORMANCE_BOND') And ct.WRITE_OFF_FLAG != 'FULL' And ct.REVERSED_FLAG = 'N' and not exists(select line.* from CSH_TRANSACTION_REFUND_LN line, CSH_TRANSACTION_REFUND head where head.REFUND_ID = line.REFUND_ID and line.SOURCE_TRANSACTION_ID = ct.TRANSACTION_ID and head.REFUND_STATUS != 'CANCEL') Order By ct.transaction_id Desc) t1
1 = 1
and t1.contract_number like #{contractNumber}
AND t1.transaction_date >= #{transactionDateFrom}
AND t1.transaction_date <= #{transactionDateTo}
AND t1.TRANSACTION_AMOUNT >= #{transactionAmountFrom}
AND t1.TRANSACTION_AMOUNT <= #{transactionAmountTo}
AND t1.transaction_type = #{transactionType}
AND t1.transaction_num like #{transactionNum}
AND t1.manufacturer_id = #{manufacturerId}
and t1.manufacturer_id_n like #{manufacturerIdN}
and t1.bp_id_vender_n like #{bpIdVenderN}
and t1.factory_id_n like #{factoryIdN}
AND t1.is_terminate = #{isTerminate}
and t1.is_terminate_n like #{isTerminateN}
AND t1.bp_name like #{bpName}
AND t1.bp_bank_account_name like #{bpBankAccountName}
AND t1.bp_bank_account_num like #{bpBankAccountNum}
AND t1.bp_type = #{bpType}

select t1.* from (select ctr.REFUND_ID, ctr.REFUND_AMOUNT, ctr.REFUND_DATE, ctr.REFUND_STATUS, ctr.payment_method, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = ctr.payment_method ) payment_method_n, (select scvb.MEANING from sys_code_b scb left join sys_code_value_b scvb on scb.code = 'HLS_WFL_STATUS' and scb.code_id = scvb.code_id where scvb.value = ctr.REFUND_STATUS) as refund_status_desc, ctr.REFUND_NUMBER, ctr.bp_id, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = ctr.bp_id) as bp_name, (select hbt.description from hls_bp_master hbm left join hls_bp_type hbt on hbm.bp_type = hbt.bp_type where hbm.bp_id = ctr.bp_id) as bp_name_category, ctr.BP_BANK_BRANCH_NAME BP_BANK_BRANCH_NAME, ctr.BP_BANK_ACCOUNT_NAME BP_BANK_ACCOUNT_NAME, ctr.BP_BANK_ACCOUNT_ID, ctr.BP_BANK_ACCOUNT_NUM BP_BANK_ACCOUNT_NUM, ctr.bp_bank_name bp_bank_name, ctr.payment_refund_status, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'PAYMENT_REFUND_STATUS_NEW' AND v.code_value = ctr.PAYMENT_REFUND_STATUS) payment_refund_status_n from csh_transaction_refund ctr order by ctr.refund_id desc) t1
1 = 1
and t1.refund_status = #{refundStatus}
and t1.refund_number like #{refundNumber}
and t1.bp_name like #{bpName}
and t1.refund_date >= #{refundDateFrom}
and t1.refund_date <= #{refundDateTo}
and t1.refund_amount >= #{refundAmountFrom}
and t1.refund_amount <= #{refundAmountTo}
AND t1.bp_name like #{bpName}
AND t1.bp_bank_account_name like #{bpBankAccountName}
AND t1.bp_bank_account_num like #{bpBankAccountNum}
AND t1.payment_refund_status = #{paymentRefundStatus}

select *
from (SELECT t.*,
(select hbm.bp_name
from hls_bp_master hbm
where hbm.bp_id = t.bp_id
) as                                                                  bp_name,

(SELECT v.meaning
FROM sys_code_value_b_v v
WHERE v.code = 'HLS_WFL_STATUS'
AND v.code_value = t.refund_status)                                refund_status_desc,
(select c.currency_name
from fnd_currency c
where c.currency_code = t.currency_code)                             currency_name,
(select cba.bank_account_num
from csh_bank_account cba
where cba.bank_account_id = t.bank_account_id)                       bank_account_num,
(select cba.bank_account_name
from csh_bank_account cba
where cba.bank_account_id = t.bank_account_id)                       bank_account_name,
(select u.description from sys_user u where u.user_id = t.created_by) created_by_name,
t.creation_date                                                       creation_date_format,

(SELECT v.meaning
FROM sys_code_value_b_v v
WHERE v.code = 'PAYMENT_REFUND_STATUS'
AND v.code_value = nvl(t.PAYMENT_REFUND_STATUS, 'NEW'))            payment_refund_status_n
FROM csh_transaction_refund t) t1


        AND t1.refund_id = #{refundId}


        AND t1.refund_flag = #{refundFlag}


        AND t1.refund_status = #{refundStatus}



        and t1.refund_number like #{refundNumber}


        AND t1.refund_date = #{refundDate}


        AND t1.refund_amount = #{refundAmount}



        and t1.bp_bank_account_num like #{bpBankAccountNum}



        and t1.bp_bank_account_name like #{bpBankAccountName}


        AND t1.creation_date=  #{creationDateFormat}



        and t1.created_by_name like #{createdByName}



        and t1.bp_name like #{bpName}



        and t1.payment_refund_status like #{paymentRefundStatus}


        and exists (select 1 from csh_transaction_refund_ln l
        where l.REFUND_ID=t1.REFUND_ID
        and l.source_transaction_id = #{sourceTransactionId})


order by t1.refund_number desc

select * from ( SELECT t.*, (select hbm.bp_name from hls_bp_master hbm,csh_transaction ct where hbm.bp_id=ct.bp_id and ct.transaction_id=t.transaction_id) as bp_name, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv, csh_transaction ct WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = ct.payment_method and ct.transaction_id = t.transaction_id) payment_method_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'HLS_WFL_STATUS' AND v.code_value = t.refund_status) refund_status_desc, (select c.currency_name from fnd_currency c where c.currency_code= t.currency_code)currency_name, (select cba.bank_account_num from csh_bank_account cba where cba.bank_account_id = t.bank_account_id) bank_account_num, (select cba.bank_account_name from csh_bank_account cba where cba.bank_account_id = t.bank_account_id) bank_account_name, (select hba.bank_account_num from hls_bp_master_bank_account hba where hba.bank_account_id = t.bp_bank_account_id)bp_bank_account_num, (select hba.bank_account_name from hls_bp_master_bank_account hba where hba.bank_account_id = t.bp_bank_account_id)bp_bank_account_name, (select hba.bank_full_name from hls_bp_master_bank_account hba where hba.bank_account_id = t.bp_bank_account_id)bp_bank_name, (select hba.bank_branch_name from hls_bp_master_bank_account hba where hba.bank_account_id = t.bp_bank_account_id)bp_bank_branch_name, (select u.description from sys_user u where u.user_id = t.created_by )created_by_name, t.creation_date creation_date_format, ( SELECT ct.TRANSACTION_TYPE FROM csh_transaction ct WHERE ct.TRANSACTION_ID = t.TRANSACTION_ID ) TRANSACTION_TYPE, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CSH301_TRANSACTION_TYPE' AND v.code_value = ( SELECT ct.TRANSACTION_TYPE FROM csh_transaction ct WHERE ct.TRANSACTION_ID = t.TRANSACTION_ID) ) transaction_type_n, ( SELECT FC.CURRENCY_NAME FROM FND_CURRENCY FC WHERE FC.CURRENCY_CODE = t.CURRENCY_CODE ) AS currency_code_n, ( SELECT c.contract_number FROM con_contract c WHERE c.contract_id = ( SELECT ct.contract_id FROM csh_transaction ct WHERE ct.TRANSACTION_ID = t.TRANSACTION_ID ) ) contract_number, ( SELECT c.contract_name FROM con_contract c WHERE c.contract_id = ( SELECT ct.contract_id FROM csh_transaction ct WHERE ct.TRANSACTION_ID = t.TRANSACTION_ID )) contract_name, nvl((select sum(cf.REFUND_AMOUNT) from csh_transaction ct,csh_transaction_refund cf where ct.TRANSACTION_ID=cf.TRANSACTION_ID and cf.REFUND_STATUS='APPROVED' and cf.TRANSACTION_ID=t.TRANSACTION_ID ),0) sum_due_amount, (select cs1.transaction_amount from csh_transaction cs1 where cs1.TRANSACTION_ID=t.TRANSACTION_ID) transaction_amount, (select cs1.transaction_amount from csh_transaction cs1 where cs1.TRANSACTION_ID=t.TRANSACTION_ID)- nvl((select sum(cf.REFUND_AMOUNT) from csh_transaction ct,csh_transaction_refund cf where ct.TRANSACTION_ID=cf.TRANSACTION_ID and cf.REFUND_STATUS='APPROVED' and cf.TRANSACTION_ID=t.TRANSACTION_ID ),0) surplus_due_amount, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'PAYMENT_REFUND_STATUS' AND v.code_value = t.PAYMENT_REFUND_STATUS) payment_refund_status_n, (select pt.COMPANY_SPV from prj_project pt where pt.project_id=( SELECT c.project_id FROM con_contract c WHERE c.contract_id = ( SELECT ct.contract_id FROM csh_transaction ct WHERE ct.TRANSACTION_ID = t.TRANSACTION_ID ))) COMPANY_SPV, ( SELECT t.company_full_name FROM fnd_company t WHERE t.company_id = (select pt.COMPANY_SPV from prj_project pt where pt.project_id=( SELECT c.project_id FROM con_contract c WHERE c.contract_id = ( SELECT ct.contract_id FROM csh_transaction ct WHERE ct.TRANSACTION_ID = t.TRANSACTION_ID ))) ) AS company_spv_n FROM csh_transaction_refund t)t1
1=1 and t1.payment_refund_status in ('APPROVING','APPROVED','PAID')
AND t1.transaction_id = #{transactionId}
AND t1.refund_id = #{refundId}
AND t1.refund_flag = #{refundFlag}
AND t1.refund_status = #{refundStatus}
and t1.refund_number like #{refundNumber}
AND t1.refund_date = #{refundDate}
AND t1.refund_amount = #{refundAmount}
and t1.bp_bank_account_num like #{bpBankAccountNum}
and t1.bp_bank_account_name like #{bpBankAccountName}
AND t1.creation_date= #{creationDateFormat}
and t1.created_by_name like #{createdByName}
and t1.contract_number like #{contractNumber}
and t1.bp_name like #{bpName}
and t1.payment_refund_status like #{paymentRefundStatus}
order by t1.refund_number desc

SELECT t1.* FROM (SELECT ct.TRANSACTION_ID, ct.TRANSACTION_NUM, ct.TRANSACTION_TYPE, ct.posted_flag, cc.CONTRACT_ID, cc.contract_number, ctrl.ln_id, ctrl.refund_id, ctrl.bank_account_id, ctrl.refund_amount, ctrl.payment_method, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = ctrl.payment_method ) payment_method_n, ctrl.bank_slip_num, ctrl.object_version_number, ctrl.request_id, ctrl.program_id, ctrl.created_by, ctrl.creation_date, ctrl.last_updated_by, ctrl.last_update_date, ctrl.last_update_login, ctrl.SOURCE_TRANSACTION_ID, ct.TRANSACTION_DATE, ct.TRANSACTION_AMOUNT, ct.CURRENCY_CODE, nvl(ct.WRITE_OFF_AMOUNT, 0) AS WRITE_OFF_AMOUNT, (SELECT m.BP_NAME FROM HLS_BP_MASTER m WHERE m.BP_ID = ct.BP_ID) AS bp_payment_name, (SELECT scvb.MEANING FROM SYS_CODE_B scb LEFT JOIN SYS_CODE_VALUE_B scvb ON scb.CODE = 'CSH301_TRANSACTION_TYPE' AND scb.CODE_ID = scvb.CODE_ID WHERE scvb.VALUE = ct.TRANSACTION_TYPE) AS transaction_type_desc, (SELECT scvb.MEANING FROM SYS_CODE_B scb LEFT JOIN SYS_CODE_VALUE_B scvb ON scb.CODE = 'CHS.CURRENCY_TYPE' AND scb.CODE_ID = scvb.CODE_ID WHERE scvb.VALUE = ct.CURRENCY_CODE) AS currency_code_desc, (SELECT nvl(SUM(cwo.csh_write_off_amount), 0) FROM csh_write_off cwo WHERE cwo.csh_transaction_id = ct.transaction_id AND cwo.reversed_flag = 'N' AND cwo.write_off_type = 'REFUND') return_write_off_amount, ( SELECT sum(ctr.REFUND_AMOUNT) FROM csh_transaction_refund ctr WHERE ctr.refund_status = 'APPROVING' AND ctr.TRANSACTION_ID = ct.TRANSACTION_ID ) refunding_amount, (nvl(ct.transaction_amount, 0) - nvl(ct.block_amount, 0) - (SELECT nvl(SUM(cwo.csh_write_off_amount), 0) FROM csh_write_off cwo WHERE cwo.csh_transaction_id = ct.transaction_id AND cwo.reversed_flag = 'N')) AS can_return_amount, (select bm.bp_name from hls_bp_master bm where bm.bp_id=ct.bp_id) bp_name FROM csh_transaction_refund_ln ctrl INNER JOIN csh_transaction ct ON ct.TRANSACTION_ID = ctrl.SOURCE_TRANSACTION_ID LEFT JOIN con_contract cc ON ct.contract_id = cc.contract_id WHERE ct.TRANSACTION_TYPE IN ('ADVANCE_RECEIPT', 'DEPOSIT', 'MANAGEMENT_FEE', 'PERFORMANCE_BOND')) t1
and t1.refund_id = #{refundId}
AND t1.transaction_id in
#{item,jdbcType=DECIMAL}

select * from (SELECT t.*, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.payment_method ) payment_method_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = t.bp_id ) as bp_name,
(SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'HLS_WFL_STATUS' AND v.code_value = t.refund_status) refund_status_desc, (select c.currency_name from fnd_currency c where c.currency_code = t.currency_code) currency_name, (select cba.bank_account_num from csh_bank_account cba where cba.bank_account_id = t.bank_account_id) bank_account_num, (select cba.bank_account_name from csh_bank_account cba where cba.bank_account_id = t.bank_account_id) bank_account_name, (select u.description from sys_user u where u.user_id = t.created_by) created_by_name, t.creation_date creation_date_format, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'PAYMENT_REFUND_STATUS_NEW' AND v.code_value = nvl(t.PAYMENT_REFUND_STATUS, 'NEW')) payment_refund_status_n FROM csh_transaction_refund t
where t.PAYMENT_REFUND_STATUS not in ('NEW') ) t1
and t1.refund_status = #{refundStatus}
and t1.refund_number like #{refundNumber}
and t1.bp_name like #{bpNameLike}
and t1.bp_bank_account_num like #{bpBankAccountNumLike}
and t1.bp_bank_account_name like #{bpBankAccountNameLike}
and t1.refund_date >= #{refundDateFrom}
and t1.refund_date <= #{refundDateTo}
and t1.refund_amount >= #{refundAmountFrom}
and t1.refund_amount <= #{refundAmountTo}

Select t.source_transaction_id transaction_id
          From csh_transaction_refund_line t
         Where t.refund_id = #{refundId}
